COPY public.subject_contents (id, module_id, subject_code, title, lesson_type, contentbuilder_id, pdf_files, quiz_content, order_index, created_at, updated_at) FROM stdin;
3	1	\N	Quiz I	quiz	\N	[]	\N	0	2026-09-16 08:20:40.44336+08	2026-09-16 08:20:40.44336+08
91	51	\N	Lesson I: Mastering Vocal Modulation, Pitch, and Pronunciation	module	\N	[]	[{"id":"1787593241966_67bgn","type":"headline","content":"Mastering Vocal Modulation, Pitch, and Pronunciation","properties":{"fontFamily":"inherit","color":"#4d4d4d","fontSize":"30px","textAlign":"center"}},{"id":"1787593192774_awsv1","type":"image","content":"/api/files/11","properties":{"width":"1184px","height":"338px","objectFit":"fill"}},{"id":"1787593301932_92x7s","type":"text","content":"Spoken communication relies heavily on the physical mechanics of voice production and the intentional modulation of vocal variables to convey meaning, authority, and emotional resonance. The foundation of effective oral delivery begins with respiratory control, where proper diaphragmatic breathing allows a speaker to project their voice steadily across a room without straining the vocal cords or running out of breath mid-sentence. When airflow is channeled smoothly through the vocal tract, the speaker gains precise control over key acoustic properties such as volume, pitch range, and speech tempo. Varying these vocal elements prevents monotone delivery, maintains listener engagement, and strategically highlights critical arguments throughout an address.","properties":{"fontFamily":"","color":"#333333","fontSize":"20","textAlign":"left","verticalAlign":"center","letterSpacing":"","lineHeight":"","backgroundColor":"#ffffff"}},{"id":"1787595410582_219sl","type":"2_col","children":[{"id":"1787595410582_219sl_c1","type":"column","children":[{"id":"1787595356579_5dpru","type":"image","content":"/api/files/13","properties":{"textAlign":"left","width":"537px","height":"406px","objectFit":"fill"}}]},{"id":"1787595410582_219sl_c2","type":"column","children":[{"id":"1787595410582_1y9xg","type":"headline","content":"Varying these vocal elements prevents monotone delivery, maintains listener engagement, and strategically highlights critical arguments throughout an address.","properties":{"fontFamily":"'Source Sans 3', sans-serif","color":"#485346","fontSize":"35","textAlign":"center","verticalAlign":"center"}}]}],"properties":{"gridTemplateColumns":"45% 55%"}},{"id":"1787595874417_ffo3m","type":"video","content":"/api/files/14","properties":{}},{"id":"1787595906192_c5gt9","type":"text","content":"<i><b>Equally critical to powerful speech delivery is precise articulation and standard pronunciation. The clear formation of individual vowel sounds and consonant blends relies on the coordinated movement of the articulators, including the tongue, lips, teeth, hard palate, and jaw. Slurred phonemes, dropped word endings, and rushed pacing often create semantic confusion and undermine the speaker’s credibility, particularly in formal presentations or academic settings.&nbsp;</b></i>","properties":{"fontFamily":"inherit","color":"#333333","fontSize":"20","textAlign":"left"}}]	0	2026-08-25 01:32:28.606+08	2026-08-25 02:26:12.26+08
92	51	\N	Lesson II: Voice Dynamics, Articulation, and Public Delivery	pdf	\N	[{"url": "/api/files/15", "name": "1787596076340_sample-local-pdf.pdf"}]	\N	0	2026-08-25 02:27:32.819+08	2026-08-25 02:51:35.261+08
94	51	\N	Quiz I: Vocal Dynamics and Non-Verbal Delivery	quiz	\N	[]	{"settings":{"fontFamily":"'Inter', sans-serif","fontSize":14,"startDate":"","startTime":"","isAssignment":false,"endDate":"2026-08-27","endTime":"19:00","timeLimitMinutes":30,"maxRetries":0},"questions":[{"id":"1787598709632","type":"title_description","title":"","description":"Test your understanding of voice modulation, articulation mechanics, kinesics, and physical stage presence covered in Lessons 1 and 2 of the Voice Dynamics, Articulation, and Public Delivery module.","image":null},{"id":"1787598726719","type":"question","questionType":"Multiple Choice","text":"Which physiological technique provides the foundation for steady vocal projection and sustained airflow without straining the vocal cords?","image":null,"points":5,"options":[{"id":"17875987267191","text":"Clavicular shallow breathing"},{"id":"17875987267192","text":"Diaphragmatic breathing","isCorrect":true},{"id":"17875987267193","text":"Rapid nasal respiration"},{"id":"1787598760787","text":"Glottal compression"}]},{"id":"1787598778158","type":"question","questionType":"True or False","text":"Delivering a presentation with an unvarying, single pitch tone (monotone) enhances audience comprehension by removing emotional distractions.","image":null,"points":5,"options":[{"id":"17875987866991","text":"True","isCorrect":false},{"id":"17875987866992","text":"False","isCorrect":true}]},{"id":"1787598792990","type":"question","questionType":"Short Answer","text":"What term refers to the study of body movement, facial expressions, gestures, and posture in non-verbal communication?","image":null,"points":5,"options":[{"id":"17875987929901","text":"Option 1"},{"id":"17875987929902","text":"Option 2"},{"id":"17875987929903","text":"Option 3"}],"correctAnswer":"Kinetics"},{"id":"1787598808831","type":"question","questionType":"Multiple Choice","text":"Which of the following physical behaviors actively reinforces a speaker’s rhetorical authority and builds trust with an audience?","image":null,"points":5,"options":[{"id":"17875988088311","text":"Pacing rapidly across the stage to cover distance"},{"id":"17875988088312","text":"Crossing arms firmly across the chest"},{"id":"17875988088313","text":"Sustained, natural eye contact across the room","isCorrect":true}]},{"id":"1787598841022","type":"question","questionType":"Short Answer","text":"Name two active physical articulators responsible for shaping distinct vowel and consonant sounds during speech production.","image":null,"points":5,"options":[{"id":"17875988410221","text":"Option 1"},{"id":"17875988410222","text":"Option 2"},{"id":"17875988410223","text":"Option 3"}],"correctAnswer":"Tongue, lips"}]}	0	2026-08-25 02:33:24.915+08	2026-08-25 03:43:36.168+08
96	52	\N	Lesson 1: Demographic Profiling and Situational Context	module	\N	[]	[{"id":"1787600877604_5jnpt","type":"image","content":"/api/files/17","properties":{"width":"575px","height":"412px","objectFit":"fill","textAlign":"center"}},{"id":"1787601027233_g3axn","type":"text","content":"<i>Effective oral rhetoric begins with a thorough diagnostic assessment of the target listeners long before the speaker takes the podium. Crafting an impactful message requires analyzing key demographic variables—such as cultural background, age distribution, prior subject knowledge, values, and socioeconomic context—to ensure that arguments resonate rather than alienate. Beyond basic listener traits, a speaker must evaluate the situational context, which includes the physical setting, time constraints, audience expectations, and whether attendance is voluntary or mandatory. By systematically diagnosing these variables, a presenter can tailor their tone, select relatable analogies, calibrate the depth of technical terminology, and anticipate potential counterarguments, thereby ensuring the discourse meets the listeners where they are.</i>","properties":{"fontFamily":"inherit","color":"#333333","fontSize":"18","textAlign":"justify","padding":"5"}},{"id":"1787601163729_xekru","type":"2_col","children":[{"id":"1787601163729_xekru_c1","type":"column","children":[{"id":"1787601103888_g3dvr","type":"headline","content":"Mastering Classical Aristotelian Rhetorical Appeals","properties":{"fontFamily":"inherit","color":"#292f61","fontSize":"50","textAlign":"center","verticalAlign":"center"}}]},{"id":"1787601163729_xekru_c2","type":"column","children":[{"id":"1787601163729_4gorv","type":"image","content":"/api/files/18","properties":{}}]}]},{"id":"1787601180157_rrxcr","type":"text","content":"Persuasive speaking relies on the strategic synthesis of the classical Aristotelian triad: <i data-path-to-node=\\"6\\" data-index-in-node=\\"91\\">ethos</i>, <i data-path-to-node=\\"6\\" data-index-in-node=\\"98\\">logos</i>, and <i data-path-to-node=\\"6\\" data-index-in-node=\\"109\\">pathos</i>. <i data-path-to-node=\\"6\\" data-index-in-node=\\"117\\">Ethos</i> establishes the speaker’s moral character, professional competence, and perceived goodwill, creating a foundation of credibility and trust without which even sound arguments are rejected. <i data-path-to-node=\\"6\\" data-index-in-node=\\"311\\">Logos</i> provides the intellectual architecture of the address through logical reasoning, clear empirical data, well-structured syllogisms, and credible evidence that withstands critical scrutiny. <i data-path-to-node=\\"6\\" data-index-in-node=\\"505\\">Pathos</i> breathes life into abstract data by engaging the listeners' emotions, values, and empathy through vivid narratives, metaphorical language, and evocative delivery. A masterful orator balances all three appeals, ensuring that <i data-path-to-node=\\"6\\" data-index-in-node=\\"736\\">pathos</i> motivates action without devolving into manipulation, while <i data-path-to-node=\\"6\\" data-index-in-node=\\"803\\">logos</i> and <i data-path-to-node=\\"6\\" data-index-in-node=\\"813\\">ethos</i> supply the rational and ethical justification for the audience to adopt the proposed viewpoint.","properties":{"fontFamily":"inherit","color":"#3b3b3b","fontSize":"18","textAlign":"left","backgroundColor":"#e5eeff","padding":"20"}}]	0	2026-08-25 03:47:41.708+08	2026-08-25 03:53:57.877+08
97	52	\N	Quiz 1: Audience Analysis & Aristotelian Rhetorical Appeals	quiz	\N	[]	{"settings":{"fontFamily":"'Inter', sans-serif","fontSize":14,"startDate":"2026-08-27","startTime":"10:00","isAssignment":true,"endDate":"2026-08-29","endTime":"09:00","timeLimitMinutes":30,"maxRetries":0},"questions":[{"id":"1787601291245","type":"title_description","title":"","description":"A 5-item evaluation covering demographic profiling, situational context evaluation, and the practical application of ethos, logos, and pathos in persuasive discourse.","image":null},{"id":"1787601299717","type":"question","questionType":"Multiple Choice","text":"A speaker who cites peer-reviewed studies, presents statistical datasets, and structures their argument using deductive syllogisms is primarily utilizing which classical rhetorical appeal?","image":null,"points":5,"options":[{"id":"17876012997171","text":"Ethos"},{"id":"17876012997172","text":"Logos"},{"id":"17876012997173","text":"Pathos"},{"id":"1787601320084","text":"Kairos"}]},{"id":"1787601329304","type":"question","questionType":"True or False","text":"Analyzing situational context involves assessing whether an audience's attendance is voluntary or mandatory, as this directly affects their initial receptivity and engagement levels.","image":null,"points":5,"options":[{"id":"17876013384971","text":"True","isCorrect":true},{"id":"17876013384972","text":"False","isCorrect":false}]},{"id":"1787601346241","type":"question","questionType":"Short Answer","text":"Which component of the classical Aristotelian triad focuses on establishing the speaker's perceived moral character, credentials, and goodwill with the audience?","image":null,"points":5,"options":[{"id":"17876013462411","text":"Option 1"},{"id":"17876013462412","text":"Option 2"},{"id":"17876013462413","text":"Option 3"}],"correctAnswer":"Ethos"},{"id":"1787601365773","type":"question","questionType":"Multiple Choice","text":"Which of the following scenarios best demonstrates an effective integration of pathos into an informative speech?","image":null,"points":5,"options":[{"id":"17876013657731","text":"Reciting a chronological timeline of tax legislation without visual aids"},{"id":"17876013657732","text":"Listing numerical variables from an experimental trial in a raw table"},{"id":"17876013657733","text":"Sharing a poignant, humanizing narrative of an individual impacted by a policy","isCorrect":true}]},{"id":"1787601400892","type":"question","questionType":"Short Answer","text":"List one demographic variables that a speaker must evaluate during audience profiling to avoid alienating listeners.","image":null,"points":5,"options":[{"id":"17876014008921","text":"Option 1"},{"id":"17876014008922","text":"Option 2"},{"id":"17876014008923","text":"Option 3"}],"correctAnswer":"Age"}]}	0	2026-08-25 03:54:42.509+08	2026-08-25 03:58:29.161+08
\.


